-- D20 L3: 取与 A001 相交的高压燃气管线，先裁剪到 A001，再分别缓冲 50 米合并为同一影响范围。复用该范围：（1）统计 A001 内正常或告警设备，按状态升序分组计数；（2）计算 A001 内各水管受影响长度（米），按长度降序、同长按编码升序，并给出总长度。边界计入，水管非空零长度接触记录保留。
-- 独立只读基准；EPSG:3857、quad_segs=8；不调用工具或执行器。
-- 影响 union 只生成一次；两分支都需受影响范围 AND A001；设备以原记录计数，水管按源编码输出完整列表。
WITH a AS (SELECT geom FROM gis_lab.construction_areas WHERE code='A001'), high AS (SELECT ST_Intersection(g.geom,a.geom) AS geom FROM gis_lab.gas_pipelines g CROSS JOIN a WHERE g.pressure_level='高压' AND ST_Intersects(g.geom,a.geom)), influence AS (SELECT ST_UnaryUnion(ST_Collect(ST_Buffer(geom,50,'quad_segs=8'))) AS geom FROM high), water_cut AS (SELECT w.code,ST_Intersection(ST_Intersection(w.geom,i.geom),a.geom) AS geom FROM gis_lab.water_pipelines w CROSS JOIN influence i CROSS JOIN a WHERE ST_Intersects(w.geom,i.geom)), water_values AS (SELECT code,ST_Length(geom) AS value FROM water_cut WHERE NOT ST_IsEmpty(geom)), device_cut AS (SELECT d.status,ST_Intersection(d.geom,a.geom) AS geom FROM gis_lab.gas_devices d CROSS JOIN influence i CROSS JOIN a WHERE d.status IN ('正常','告警') AND ST_Intersects(d.geom,i.geom)), device_grouped AS (SELECT status,count(*) AS n FROM device_cut WHERE NOT ST_IsEmpty(geom) GROUP BY status) SELECT jsonb_build_object('device_groups',COALESCE((SELECT jsonb_agg(jsonb_build_object('group',jsonb_build_object('status',status),'value',n,'feature_count',n) ORDER BY status COLLATE "C") FROM device_grouped),'[]'::jsonb),'device_unit','feature','water_groups',COALESCE((SELECT jsonb_agg(jsonb_build_object('group',jsonb_build_object('source_code',code),'value',value,'feature_count',1) ORDER BY value DESC,code COLLATE "C") FROM water_values),'[]'::jsonb),'water_unit','meter','total_length',jsonb_build_object('value',(SELECT COALESCE(sum(value),0) FROM water_values),'unit','meter','measure','length','measure_srid',3857,'feature_count',(SELECT count(*) FROM water_values))) AS answer;
